message:
Running command: cd /tmp/fuzzbuild && cp /workspace/repo-vul/src-vul/spice-usbredir/fuzzing/usbredirparserfuzz.cc debug_fuzz2.cc && python3 - << 'EOF'
import re
with open('debug_fuzz2.cc') as f:
    src = f.read()
# Add debug prints
src = src.replace('''    if (fdp->ConsumeBool() && try_unserialize(parser.get(), fdp.get()) != 0) {
        goto out;
    }''', '''    if (fdp->ConsumeBool() && try_unserialize(parser.get(), fdp.get()) != 0) {
        fprintf(stderr, "[dbg] unserialize failed\\n");
        goto out;
    }
    fprintf(stderr, "[dbg] after unserialize remaining=%zu has_write=%d\\n", fdp->remaining_bytes(), usbredirparser_has_data_to_write(parser.get()));''')
src = src.replace('''        if (fdp->ConsumeBool() && try_serialize(parser.get()) != 0) {
            goto out;
        }

        if (fdp->remaining_bytes() > 0) {
            ret = usbredirparser_do_read(parser.get());''', '''        if (fdp->ConsumeBool() && try_serialize(parser.get()) != 0) {
            fprintf(stderr, "[dbg] serialize1 failed\\n");
            goto out;
        }
        fprintf(stderr, "[dbg] loop remaining=%zu has_write=%d\\n", fdp->remaining_bytes(), usbredirparser_has_data_to_write(parser.get()));

        if (fdp->remaining_bytes() > 0) {
            ret = usbredirparser_do_read(parser.get());
            fprintf(stderr, "[dbg] do_read ret=%d remaining=%zu\\n", ret, fdp->remaining_bytes());''')
src = src.replace('''            if (fdp->ConsumeBool() && try_serialize(parser.get()) != 0) {
                goto out;
            }''', '''            if (fdp->ConsumeBool() && try_serialize(parser.get()) != 0) {
                fprintf(stderr, "[dbg] serialize2 failed\\n");
                goto out;
            }
            fprintf(stderr, "[dbg] after serialize2 remaining=%zu has_write=%d\\n", fdp->remaining_bytes(), usbredirparser_has_data_to_write(parser.get()));''')
with open('debug_fuzz2.cc','w') as f:
    f.write(src)
print("done")
EOF
g++ -c -I. -I/workspace/repo-vul/src-vul/spice-usbredir/fuzzing -I/workspace/repo-vul/src-vul/spice-usbredir/usbredirparser -I/workspace/repo-vul/src-vul/spice-usbredir -O1 -g debug_fuzz2.cc -o debug_fuzz2.o 2>&1 | head; echo "EXIT: ${PIPESTATUS[0]}"; g++ -O1 -g -fsanitize=address usbredirparser.o usbredirfilter.o debug_fuzz2.o standalone.o -o debug_fuzz2 2>&1 | head; echo "LINK: ${PIPESTATUS[0]}"

